 if(kind==='giantmushroom'){for(let i=0;i<3;i++){const x=(i-1)*17,z=i%2?12:-5,h=38+i*16;v.taper(x,0,z,h,4,2,pale);ell(x,h,z,22,8,21,leaf);for(let j=0;j<16;j++){const a=j*TAU/16;beam([x,h-3,z],[x+Math.cos(a)*20,h-3,z+Math.sin(a)*20],.7,pale);}for(let j=0;j<9;j++){const X=x+(R()-.5)*25,Z=z+(R()-.5)*25;ell(X,h+6,Z,3,1.5,3,B.accent);g.set(Math.round(X),h+7,Math.round(Z),0xffffff);}}}
