function tickSurvival(dt){if(G.mode!=='outdoors')return;WILD.elapsed+=dt;WILD.chunkClock+=dt;if(WILD.chunkClock>.25){WILD.chunkClock=0;streamWild();}if(WILD.phase==='intermission'){WILD.timer-=dt;if(WILD.timer<=0)startSurvivalWave();return;}if(WILD.phase==='gate')return;WILD.spawnClock-=dt;const alive=G.enemies.filter(e=>!e.dead&&e.waveId===WILD.wave);if(WILD.pending>0&&WILD.spawnClock<=0&&alive.length<90){const burst=Math.min(WILD.pending,2+Math.floor(WILD.wave/5));for(let i=0;i<burst;i++)alive.push(spawnWaveEnemy());WILD.spawnClock=Math.max(.35,1.45-WILD.wave*.025);}if(WILD.pending===0){WILD.phase='fighting';if(alive.length===0){player.gold+=65+WILD.wave*12;RUN.shards+=2+Math.floor(WILD.wave/5);player.hp=Math.min(player.maxhp,player.hp+player.maxhp*.17);player.potions++;if(WILD.wave%10===0){WILD.phase='gate';createRegionPortal(player.pos.add(V3(0,0,-4)));toast('Abomination overcome. Enter the gate to the next region.','#d7e6b8');}else{WILD.phase='intermission';WILD.timer=12;toast('Wave '+WILD.wave+' cleared · supplies recovered','#cfdfb0');}saveGame(true);}}}
