const playerBeforeAdventure=updatePlayer;updatePlayer=function(dt){player.statusSlow=Math.max(0,(player.statusSlow||0)-dt);const speed=player.speed;if(player.statusSlow>0)player.speed*=.67;playerBeforeAdventure(dt);player.speed=speed;};
loadLevel=async function(depth,carry,seed,snapshot,begin=true,mode){if(loadingLevel)return;G.mode=mode||snapshot?.worldMode||'dungeon';WILD.chunks.clear();WILD.lastChunk=null;WILD.lastBiome=null;WILD.hazards=[];WILD.debris=[];WILD.campMeshes=[];WILD.campBlocks=[];WILD.portal=null;WILD.portalPos=null;WILD.broken=new Map(snapshot?.destruction||[]);destructibles.clear();propBuckets.clear();const wild=snapshot?.wild;WILD.seed=seed??snapshot?.seed??0;WILD.depthBase=wild?.depthBase??(snapshot?.worldMode==='outdoors'?10:4);WILD.wave=wild?.wave||0;WILD.phase=wild?.phase||'intermission';WILD.timer=wild?.timer??18;WILD.pending=wild?.pending||0;WILD.spawnClock=wild?.spawnClock||0;WILD.region=wild?.region||0;WILD.elapsed=wild?.elapsed||0;WILD.abomination=!!wild?.abomination;WILD.camp=wild?.camp?V3(...wild.camp):V3();WILD.spawn=snapshot?.worldMode==='outdoors'?V3(...snapshot.player.pos):WILD.camp.clone();WILD.opened=new Set(wild?.opened||[]);WILD.sleepingDrops=new Map(wild?.sleepingDrops||[]);WILD.lootId=wild?.lootId||0;RUN.forgePos=null;RUN.shrinePos=null;await A3.loadLevel(depth,carry,seed,snapshot,begin);if(G.mode==='outdoors'&&G.running){cam.maxZ=110;if(wild?.portalPos)createRegionPortal(V3(...wild.portalPos));}propIndex();};
makeSave=function(){const d=A3.makeSave();d.version=3;d.worldMode=G.mode;d.build=ADVENTURE_BUILD;d.destruction=[...WILD.broken];d.hazards=WILD.hazards.map(h=>({pos:h.pos.asArray(),radius:h.radius,t:h.t,damage:h.damage,color:h.color,kind:h.kind,owner:h.owner?.eid}));d.enemies=d.enemies.map(saved=>{const e=G.enemies.find(q=>q.eid===saved.eid);return{...saved,eliteType:e.eliteType||null,waveId:e.waveId||0,chunk:e.chunk||null,maxhp:e.maxhp,dmg:e.dmg,speed:e.speed,bossPhase:e.bossPhase||1,specialCd:e.specialCd,specialCount:e.specialCount||0,ward:e.ward||0,status:e.status};});if(G.mode==='outdoors')d.wild={depthBase:WILD.depthBase,wave:WILD.wave,phase:WILD.phase,timer:WILD.timer,pending:WILD.pending,spawnClock:WILD.spawnClock,region:WILD.region,elapsed:WILD.elapsed,abomination:WILD.abomination,camp:WILD.camp.asArray(),opened:[...WILD.opened],sleepingDrops:[...WILD.sleepingDrops],lootId:WILD.lootId,portalPos:WILD.portalPos?.asArray()||null};return d;};
validSave=function(d){if(!d||![2,3].includes(d.version))return false;const safe={...d,version:2};if(!A3.validSave(safe))return false;const finite=(n,min=0,max=1e12)=>Number.isFinite(n)&&n>=min&&n<=max,position=p=>Array.isArray(p)&&p.length===3&&p.every(n=>finite(n,-1e9,1e9));try{if(d.worldMode&&!['dungeon','outdoors'].includes(d.worldMode))return false;if(d.destruction&&(!Array.isArray(d.destruction)||!d.destruction.every(p=>Array.isArray(p)&&typeof p[0]==='string'&&p[0].length<200&&p[1]&&finite(p[1].hp)&&typeof p[1].dead==='boolean')))return false;const items=[...d.player.bag,...Object.values(d.player.gear),...(d.vendor?.stock||[]).map(r=>r.item)];if(items.some(it=>it?.armorSet&&!ARMOR_SETS[it.armorSet]))return false;if(d.worldMode==='outdoors'){const w=d.wild;if(!w||(w.depthBase!==undefined&&(!Number.isInteger(w.depthBase)||w.depthBase<4))||!Number.isSafeInteger(w.wave)||w.wave<0||!['intermission','spawning','fighting','gate'].includes(w.phase)||!finite(w.pending)||!finite(w.elapsed)||!finite(w.region)||!finite(w.timer,-1)||!position(w.camp)||!Array.isArray(w.opened)||!w.opened.every(k=>typeof k==='string')||!Array.isArray(w.sleepingDrops)||!w.sleepingDrops.every(([k,v])=>typeof k==='string'&&position(v.pos)&&A3.validSave({...safe,player:{...safe.player,bag:v.item?[v.item]:[]}}))||w.portalPos&&!position(w.portalPos))return false;}if(d.hazards&&(!Array.isArray(d.hazards)||!d.hazards.every(h=>position(h.pos)&&finite(h.radius,.01,100)&&finite(h.t,-1,60)&&finite(h.damage)&&/^#[a-f0-9]{6}$/i.test(h.color))))return false;return true;}catch{return false;}};
restoreWorld=function(d){A3.restoreWorld(d);for(const saved of d.enemies){const e=G.enemies.find(q=>q.eid===saved.eid);if(!e)continue;if(saved.maxhp){e.maxhp=saved.maxhp;e.hp=clamp(saved.hp,1,e.maxhp);}for(const k of['waveId','chunk','bossPhase','specialCount','ward'])if(saved[k]!==undefined)e[k]=saved[k];for(const k of['dmg','speed','specialCd'])if(Number.isFinite(saved[k]))e[k]=saved[k];if(saved.status)e.status={...e.status,...saved.status};if(saved.eliteType&&ELITE_TYPES[saved.eliteType]){e.eliteType=saved.eliteType;e.ability=ELITE_TYPES[saved.eliteType].ability;e.name=ELITE_TYPES[saved.eliteType].name+' · '+e.spec.name;}if(e.boss)G.bossRef=e;}
 if(G.mode==='outdoors'){for(const e of G.enemies)if(e.passive&&e.chunk&&!WILD.chunks.has(e.chunk)){killNode(e.rig.root);e.removed=true;}G.enemies=G.enemies.filter(e=>!e.removed);for(const chunk of WILD.chunks.values())chunk.wild=G.enemies.filter(e=>e.passive&&e.chunk===chunk.key);G.bossDown=false;}for(const h of d.hazards||[])hazard(V3(...h.pos),h.radius,Math.max(.3,h.t),h.damage,h.color,h.kind,G.enemies.find(e=>e.eid===h.owner)||null);propIndex();};
updateObjectives=function(){if(G.mode!=='outdoors'){A3.updateObjectives();$('questTitle').textContent=G.depth===4?'Defeat the abomination':'Complete the three dungeon floors';return;}const living=G.enemies.filter(e=>e.waveId===WILD.wave&&!e.dead).length;$('questTitle').textContent=WILD.phase==='gate'?'A new region awaits':'Survive the Shattered Wilds';$('questRows').innerHTML='<div>Wave <b>'+WILD.wave+'</b> · Region '+(WILD.region+1)+'</div><div>'+ (WILD.phase==='intermission'?'Next wave in '+Math.ceil(Math.max(0,WILD.timer))+' seconds':WILD.phase==='gate'?'Enter the luminous gate to continue':living+' enemies alive · '+WILD.pending+' approaching')+'</div><div>Next abomination: wave '+(Math.floor(WILD.wave/10)+1)*10+'</div><div>Survived '+Math.floor(WILD.elapsed/60)+'m '+Math.floor(WILD.elapsed%60)+'s</div>';$('goldHud').textContent='◈ '+player.gold+' gold · '+RUN.shards+' shards';$('zoneLabel').textContent=outdoorBiome(player.pos.x,player.pos.z).short.toUpperCase();};
updateExploration=function(){if(G.mode!=='outdoors')return A3.updateExploration();const b=outdoorBiome(player.pos.x,player.pos.z);if(WILD.lastBiome!==b.short){WILD.lastBiome=b.short;$('areaBanner').innerHTML='<h2>'+escaped(b.name)+'</h2><p>SHATTERED WILDS · REGION '+(WILD.region+1)+'</p>';$('areaBanner').classList.add('show');G.bannerUntil=G.time+3.5;}if(G.bannerUntil<G.time)$('areaBanner').classList.remove('show');for(const e of G.enemies)if(!e.dead&&BABYLON.Vector3.Distance(e.pos,player.pos)<15)RUN.journal.add(e.key);};
drawMinimap=function(){if(G.mode!=='outdoors')return A3.drawMinimap();const c=$('minimap'),g=c.getContext('2d'),s=c.width/110,center=c.width/2;g.setTransform(1,0,0,1,0,0);g.fillStyle='#0d1c22';g.fillRect(0,0,c.width,c.height);for(const chunk of WILD.chunks.values()){const x=center-(chunk.x*32-player.pos.x)*s,y=c.height/2+(chunk.z*32-player.pos.z)*s,b=outdoorBiome(chunk.x*32+16,chunk.z*32+16);g.fillStyle=b.rock[0];g.fillRect(x-32*s,y,32*s-.5,32*s-.5);}const dot=(p,r,color)=>{const x=center-(p.x-player.pos.x)*s,y=c.height/2+(p.z-player.pos.z)*s;g.fillStyle=color;g.beginPath();g.arc(x,y,r,0,TAU);g.fill();};for(const e of G.enemies)if(!e.dead)dot(e.pos,e.boss?4:e.elite?3:2,e.passive?'#a4c896':e.boss?'#e195cc':'#e89880');if(vendor)dot(vendor.pos,4,'#f0d19a');if(WILD.portalPos)dot(WILD.portalPos,4,'#d1f3dc');dot(player.pos,3.2,'#8be2ce');$('mmCount').textContent='Wave '+WILD.wave;};
showTitle=function(){A3.showTitle();const foot=$('startFoot');if(foot)foot.textContent='3-floor dungeon + abomination arena · 12 biomes · endless survival';const box=$('veilBox');if(box&&!$('buildMarker')?.parentNode){const mark=document.createElement('div');mark.id='buildMarker';mark.className='buildMarker';mark.textContent='BEYOND THE CROWN · '+CATALOG.weapons+' weapons · '+CATALOG.armorFamilies+' armor collections';box.appendChild(mark);}};
const controlsBeforeAdventure=showControls;showControls=function(){controlsBeforeAdventure();$('modalBody').insertAdjacentHTML('beforeend','<p>Attack foliage, timber, pottery, bones, and breakable mineral formations to destroy them and uncover supplies. Equipment found in ordinary objects is usually low level; exceptional relics are extremely rare.</p><p>Complete three dungeon floors and defeat the abomination in the Cinder Crucible to enter the endless Shattered Wilds. Clear each wave; every tenth wave ends with an abomination and a gate to a new region. Three or five pieces from one armor collection grant set bonuses.</p>');};
